class Solution:

	def nthCharacter(self, S, R, N):
		f = N // 2 ** R
		k = N % 2 ** R
		x = S[f]

		def manu(N, k):
			if N == 0:
				return x
			parent = manu(N - 1, k // 2)
			if parent == '1' and k % 2 == 0 or (parent == '0' and k % 2 == 1):
				return '1'
			else:
				return '0'
		return manu(R, k)
